var objTableDepreciation;
var objTableVouchers;

$(document).ready(function( )
{
	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");

		if (!objFV.validate("ddYear", "B", "Please select the Financial Year."))
			return false;

		if (!objFV.validate("ddMonth", "B", "Please select the Month."))
			return false;		


		$("#BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
	
	
	
	
	
	objTableDepreciation = $("#DepreciationDataGrid").dataTable( {   sDom            : '<"H"f<"toolbar">>t<"F"ip>',
																	 aoColumnDefs    : [ { bSortable:false, aTargets:[4] } ],
																	 oLanguage       : { sEmptyTable:"No record found", sInfoEmpty:"0 records", sZeroRecords:"No matching record found" },
																	 aaSorting       : [ [ 0, "asc" ] ],
																	 bJQueryUI       : true,
																	 sPaginationType : "full_numbers",
																	 bPaginate       : true,
																	 bLengthChange   : false,
																	 iDisplayLength  : parseInt($("#RecordsPerPage").val( )),
																	 bFilter         : true,
																	 bSort           : true,
																	 bInfo           : true,
																	 bStateSave      : false,
																	 bProcessing     : false,
																	 bAutoWidth      : false
																   } );
											


	$(document).on("click", "#DepreciationDataGrid div.depreciation", function(event)
	{
		if ($(this).html( ).indexOf("<form") >= 0)
			return true;
	
		
		var objDepreciation = $(this);
		var fDepreciation   = $(this).attr("depreciation");

		
		$(this).html("<form name='frmDepreciation' id='frmDepreciation" + objDepreciation.attr("id") + "' onsubmit='return false;'>" +
					 "<div style='display:inline-block; margin-right:8px;'><input type='text' name='txtDepreciation' id='txtDepreciation' value='" + fDepreciation + "' maxlength='5' size='5' class='textbox' /></div>" +
					 "<button id='BtnSave'>Save</button>" +
					 "<button id='BtnCancel'>Cancel</button>" + 
					 "</form>");

		$("#frmDepreciation" + objDepreciation.attr("id") + " #BtnSave").button({ icons:{ primary:'ui-icon-check' }, text:false }).css("display", "inline-block").css("margin-right", "5px");
		$("#frmDepreciation" + objDepreciation.attr("id") + " #BtnCancel").button({ icons:{ primary:'ui-icon-closethick' }, text:false }).css("display", "inline-block");
		$("#frmDepreciation" + objDepreciation.attr("id") + " #txtDepreciation").focus( );


		$(document).on("click", "#frmDepreciation" + objDepreciation.attr("id") + " #BtnCancel", function( )
		{
			objDepreciation.html(objDepreciation.attr("depreciation"));
			
			return false;
		});

		
		$(document).on("click", "#frmDepreciation" + objDepreciation.attr("id") + " #BtnSave", function( )
		{
			var fDepreciation = parseFloat($("#frmDepreciation" + objDepreciation.attr("id") + " #txtDepreciation").val( ));
			
			if (isNaN(fDepreciation) || fDepreciation > 100)
			{
				objDepreciation.html(objDepreciation.attr("depreciation"));
				
				return false;
			}
			

			objDepreciation.html("<img src='images/backup.gif' width='20' alt='' title='' />");
			
			
			$.post("ajax/accounts/save-depreciation.php", 
				{ AccountId:objDepreciation.attr("id"), Depreciation:fDepreciation, Type:"Percentage" },

				function (sResponse)
				{			       
					objDepreciation.html(sResponse);
					objDepreciation.attr("depreciation", sResponse);
				},

				"text");
			
			return false;
		});
		
		
		event.stopPropagation( );
	});
	


	$(document).on("click", "#DepreciationDataGrid div.ledger", function(event)
	{
		if ($(this).html( ).indexOf("<form") >= 0)
			return true;
	
		
		var objLedger = $(this);
		var sLedger   = $(this).attr("ledger");
		var sParent   = $(this).attr("parent");

		
		$(this).html("<form name='frmLedger' id='frmLedger" + objLedger.attr("id") + "' onsubmit='return false;'>" +
					 "<div style='display:inline-block; margin-right:8px; width:calc(100% - 70px);'><input type='text' name='txtLedger' id='txtLedger' value='" + ((sLedger == "-") ? "" : sLedger)	+ "' maxlength='250' class='textbox' style='width:98%; max-width:98%;' /></div>" +
					 "<button id='BtnSave'>Save</button>" +
					 "<button id='BtnCancel'>Cancel</button>" + 
					 "</form>");

		$("#frmLedger" + objLedger.attr("id") + " #BtnSave").button({ icons:{ primary:'ui-icon-check' }, text:false }).css("display", "inline-block").css("margin-right", "5px");
		$("#frmLedger" + objLedger.attr("id") + " #BtnCancel").button({ icons:{ primary:'ui-icon-closethick' }, text:false }).css("display", "inline-block");
		
		
		$("#frmLedger" + objLedger.attr("id") + " #txtLedger").autocomplete({ source:("ajax/get-ledgers-list.php?ParentCode=" + sParent), minLength:2 });
		$("#frmLedger" + objLedger.attr("id") + " #txtLedger").focus( );

		$(document).on("keydown", ("#frmLedger" + objLedger.attr("id") + " #txtLedger"), function(e)
		{
			if (e.which == 8 || e.which == 46)
				$(this).val("");
		});			


		$(document).on("click", "#frmLedger" + objLedger.attr("id") + " #BtnCancel", function( )
		{
			objLedger.html(objLedger.attr("ledger"));
			
			return false;
		});

		
		$(document).on("click", "#frmLedger" + objLedger.attr("id") + " #BtnSave", function( )
		{
			var sLedger = $("#frmLedger" + objLedger.attr("id") + " #txtLedger").val( );
/*
			if (sLedger == "")
			{
				objLedger.html(objLedger.attr("ledger"));
				
				return false;
			}
*/

			objLedger.html("<img src='images/backup.gif' width='20' alt='' title='' />");
			
			
			$.post("ajax/accounts/save-depreciation.php", 
				{ AccountId:objLedger.attr("id"), Ledger:sLedger, Type:"Ledger", Parent:sParent },

				function (sResponse)
				{			       
					objLedger.html(sResponse);
					objLedger.attr("ledger", sResponse);
				},

				"text");
			
			return false;
		});
		
		
		event.stopPropagation( );
	});
	
	
	
	
	objTableVouchers = $("#VouchersDataGrid").dataTable( {   sDom            : '<"H"f<"toolbar">>t<"F"ip>',
															 aoColumnDefs    : [ { bSortable:false, aTargets:[5] } ],
															 oLanguage       : { sEmptyTable:"No record found", sInfoEmpty:"0 records", sZeroRecords:"No matching record found" },
															 aaSorting       : [ [ 0, "asc" ] ],
															 bJQueryUI       : true,
															 sPaginationType : "full_numbers",
															 bPaginate       : true,
															 bLengthChange   : false,
															 iDisplayLength  : parseInt($("#RecordsPerPage").val( )),
															 bFilter         : true,
															 bSort           : true,
															 bInfo           : true,
															 bStateSave      : false,
															 bProcessing     : false,
															 bAutoWidth      : false,
															 
															 fnDrawCallback  : function( )
																			   {
																				   $(".details").tipTip( );
																			   }
														   } );
														   
														   
	$(document).on("click", "#VouchersDataGrid .icnView", function(event)
	{
		var iVoucherId = this.id;

		$.colorbox({ href:("accounts/view-voucher.php?VoucherId=" + iVoucherId), width:"1000px", maxWidth:"90%", height:"600px", iframe:true, opacity:"0.50", overlayClose:true });

		event.stopPropagation( );
	});


	$(document).on("click", "#VouchersDataGrid .icnDelete", function(event)
	{
		var iVoucherId = this.id;
		var objRow     = objTableVouchers.fnGetPosition($(this).closest('tr')[0]);

		$("#ConfirmDelete").dialog(   { resizable : false,
										width     : 420,
										height    : 125,
										modal     : true,
										buttons   : { "Delete" : function( )
																  {
																		$.post("ajax/accounts/delete-voucher.php",
																			{ Vouchers:iVoucherId },

																			function (sResponse)
																			{
																				var sParams = sResponse.split("|-|");

																				showMessage("#VouchersGridMsg", sParams[0], sParams[1]);

																				if (sParams[0] == "success")
																					objTableVouchers.fnDeleteRow(objRow);
																			},

																			"text");

																		$(this).dialog("close");
																  },

														Cancel  : function( )
																  {
																		$(this).dialog("close");
																  }
											 }
									  });

		event.stopPropagation( );
	});
});

