var objTable;

$(document).ready(function( )
{
	$("#BtnBackup").button({ icons:{ primary:'ui-icon-disk' } });


	$("#BtnBackup").click(function( )
	{
		$("body").append('<div id="Overlay"></div>');
		$("#Overlay").addClass("ui-widget-overlay");
		$("#Overlay").css({ width:($(window).width( ) + "px"), height:($(window).height( ) + "px"), zIndex:99999999 });
	});





	objTable = $("#DataGrid").dataTable( { sDom            : '<"H"f<"TableTools">>t<"F"ip>',
										   aoColumnDefs    : [ { bSortable:false, aTargets:[4] } ],
										   oLanguage       : { sEmptyTable:"No record found", sInfoEmpty:"0 records", sZeroRecords:"No matching record found" },
										   bJQueryUI       : true,
										   sPaginationType : "full_numbers",
										   bPaginate       : true,
										   bLengthChange   : false,
										   iDisplayLength  : parseInt($("#RecordsPerPage").val( )),
										   bFilter         : true,
										   bSort           : true,
										   bInfo           : true,
										   bStateSave      : false,
										   bProcessing     : false,
										   bAutoWidth      : false } );


	$("#BtnSelectAll").click(function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
		{
			if (!$(objRows[i]).hasClass("selected"))
				$(objRows[i]).addClass("selected");
		}

		$("#BtnMultiDelete").show( );
	});


	$("#BtnSelectNone").click(function( )
	{
		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
			$(objRows[i]).removeClass("selected");

		$("#BtnMultiDelete").hide( );
	});


	$(document).on("click", "#DataGrid tr", function( )
	{
		if ($(this).find("img.icnDelete").length == 0)
			return false;


		if ($(this).hasClass("selected"))
			$(this).removeClass("selected");

		else
			$(this).addClass("selected");


		var bSelected = false;
		var objRows   = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
		{
			if ($(objRows[i]).hasClass("selected"))
			{
				bSelected = true;

				break;
			}
		}

		if (bSelected == true)
			$("#BtnMultiDelete").show( );

		else
			$("#BtnMultiDelete").hide( );
	});


	$("#tabs-1 .TableTools").prepend('<button id="BtnMultiDelete">Delete Selected Rows</button>');
	$("#BtnMultiDelete").button({ icons:{ primary:'ui-icon-trash' } });
	$("#BtnMultiDelete").hide( );


	$("#BtnMultiDelete").click(function( )
	{
		var sBackups        = "";
		var objSelectedRows = new Array( );

		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
		{
			if ($(objRows[i]).hasClass("selected"))
			{
				if (sBackups != "")
					sBackups += ",";

				sBackups += objRows[i].id;

				objSelectedRows.push(objRows[i]);
			}
		}

		if (sBackups != "")
		{
			$("#ConfirmMultiDelete").dialog( { resizable : false,
						           width     : 420,
						      	   height    : 110,
						           modal     : true,
						           buttons   : { "Delete" : function( )
									            {
											     $.post("ajax/management/delete-backup.php",
												    { Type:"Database", Backups:sBackups },

												    function (sResponse)
												    {
													    var sParams = sResponse.split("|-|");

													    showMessage("#PageMsg", sParams[0], sParams[1]);

													    if (sParams[0] == "success")
													    {
													         for (var i = 0; i < objSelectedRows.length; i ++)
														      objTable.fnDeleteRow(objSelectedRows[i]);

													          $("#BtnMultiDelete").hide( );


														  if ($("#SelectButtons").length == 1)
														  {
														  	if (objTable.fnGetNodes( ).length > 5 && $("#DataGrid .icnDelete").length > 0)
																$("#SelectButtons").show( );

														  	else
																$("#SelectButtons").hide( );
														  }
													    }
												    },

												    "text");

											    $(this).dialog("close");
									            },

								          Cancel  : function( )
									            {
											     $(this).dialog("close");

									            }
								       }
						         });
		}
	});


	$(document).on("click", "#DataGrid .icnRestore", function(event)
	{
		var sActionUrl = this.id;

		$("#ConfirmRestore").dialog( { resizable : false,
		                               width     : 420,
		                               height    : 135,
		                               modal     : true,
		                               buttons   : { "Restore" : function( )
		                                                         {
																	$("body").append('<div id="Overlay"></div>');
																	$("#Overlay").addClass("ui-widget-overlay");
																	$("#Overlay").css({ width:($(window).width( ) + "px"), height:($(window).height( ) + "px"), zIndex:99999999 });

		                                                       		document.location = sActionUrl;
		                                                         },

		                                              Cancel  : function( )
		                                                        {
		                                                            	$(this).dialog("close");

		                                                            	return false;
		                                                        }
		                                          }
		                            });

		event.stopPropagation( );
	});


	$(document).on("click", "#DataGrid .icnDelete", function(event)
	{
		var sBackup = this.id;
		var objRow  = objTable.fnGetPosition($(this).closest('tr')[0]);

		$("#ConfirmDelete").dialog( { resizable : false,
		                              width     : 420,
		                              height    : 110,
		                              modal     : true,
		                              buttons   : { "Delete" : function( )
		                                                       {
																	$.post("ajax/management/delete-backup.php",
																		{ Type:"Database", Backups:sBackup },

																		function (sResponse)
																		{
																			var sParams = sResponse.split("|-|");

																			showMessage("#PageMsg", sParams[0], sParams[1]);

																			if (sParams[0] == "success")
																				objTable.fnDeleteRow(objRow);


																			if ($("#SelectButtons").length == 1)
																			{
																				if (objTable.fnGetNodes( ).length > 5 && $("#DataGrid .icnDelete").length > 0)
																					$("#SelectButtons").show( );

																				else
																					$("#SelectButtons").hide( );
																			}
																		},

																		"text");

		                                                      	    	$(this).dialog("close");
		                                                       },

		                                             Cancel  : function( )
		                                                       {
		                                                            	$(this).dialog("close");

		                                                            	return false;
		                                                       }
		                                          }
		                            });

		event.stopPropagation( );
	});
});

