	$(document).on("click", "#BtnMultiDelete", function( )
	{
		var sSources        = "";
		var objSelectedRows = new Array( );

		var objRows = objTable.fnGetNodes( );

		for (var i = 0; i < objRows.length; i ++)
		{
			if ($(objRows[i]).hasClass("selected"))
			{
				if (sSources != "")
					sSources += ",";

				sSources += objRows[i].id;

				objSelectedRows.push(objRows[i]);
			}
		}

		if (sSources != "")
		{
			$("#ConfirmMultiDelete").dialog( {   resizable : false,
												 width     : 420,
												 height    : 110,
												 modal     : true,
												 buttons   : { "Delete" : function( )
																		{
																			 $.post("ajax/students/delete-inquiry-source.php",
																				{ Sources:sSources },

																				function (sResponse)
																				{
																					var sParams = sResponse.split("|-|");

																					showMessage("#GridMsg", sParams[0], sParams[1]);

																					if (sParams[0] == "success")
																					{
																						 for (var i = 0; i < objSelectedRows.length; i ++)
																							  objTable.fnDeleteRow(objSelectedRows[i]);

																						  $("#BtnMultiDelete").hide( );
																					}
																				},

																				"text");

																			$(this).dialog("close");
																		},

															  Cancel  : function( )
																		{
																			$(this).dialog("close");
																		}
													   }
											  });
		}
	});


	$(document).on("click", "#DataGrid .icnToggle", function(event)
	{
		var objIcon = this;
		var objRow  = objTable.fnGetPosition($(this).closest('tr')[0]);

		$(objIcon).removeClass( ).addClass("icon");

		$.post("ajax/students/toggle-inquiry-source.php",
			{ SourceId:objIcon.id },

			function (sResponse)
			{
				var sParams = sResponse.split("|-|");

				showMessage("#GridMsg", sParams[0], sParams[1]);


				if (sParams[0] == "success")
				{
					var iColumn = 0;

					$("#DataGrid thead tr th").each(function(iIndex)
					{
						if ($(this).text( ) == "Status")
							iColumn = iIndex;
					});


					if (objIcon.src.indexOf("success.png") != -1)
					{
						objIcon.src = objIcon.src.replace("success.png", "error.png");

						objTable.fnUpdate("In-Active", objRow, iColumn, false);
					}

					else
					{
						objIcon.src = objIcon.src.replace("error.png", "success.png");

						objTable.fnUpdate("Active", objRow, iColumn, false);
					}
				}

				$(objIcon).removeClass("icon").addClass("icnToggle");
			},

			"text");

		event.stopPropagation( );
	});


	$(document).on("click", "#DataGrid .icnEdit", function(event)
	{
		var iSourceId = this.id;
		var iIndex    = objTable.fnGetPosition($(this).closest('tr')[0]);

		$.colorbox({ href:("students/edit-inquiry-source.php?SourceId=" + iSourceId + "&Index=" + iIndex), width:"420px", height:"300px", iframe:true, opacity:"0.50", overlayClose:false });

		event.stopPropagation( );
	});


	$(document).on("click", "#DataGrid .icnDelete", function(event)
	{
		var iSourceId = this.id;
		var objRow    = objTable.fnGetPosition($(this).closest('tr')[0]);

		$("#ConfirmDelete").dialog( {   resizable : false,
										width     : 420,
										height    : 110,
										modal     : true,
										buttons   : { "Delete" : function( )
															   {
																	$.post("ajax/students/delete-inquiry-source.php",
																		{ Sources:iSourceId },

																		function (sResponse)
																		{
																			var sParams = sResponse.split("|-|");

																			showMessage("#GridMsg", sParams[0], sParams[1]);

																			if (sParams[0] == "success")
																				objTable.fnDeleteRow(objRow);
																		},

																		"text");

																	$(this).dialog("close");
															   },

													 Cancel  : function( )
															   {
																	$(this).dialog("close");
															   }
												  }
									});

		event.stopPropagation( );
	});



	$("#frmRecord #BtnReset").click(function( )
	{
		$("#frmRecord")[0].reset( );
		$("#RecordMsg").hide( );
		$("#frmRecord #txtName").focus( );

		return false;
	});


	$("#frmRecord #txtName").blur(function( )
	{
		if ($(this).val( ) == "")
			return;

		$.post("ajax/students/check-inquiry-source.php",
			{ Name:$(this).val( ) },

			function (sResponse)
			{
				if (sResponse == "USED")
				{
					showMessage("#RecordMsg", "info", "The specified Inquiry Source already exists in the System.");

					$("#DuplicateSource").val("1");
				}

				else
				{
					$("#RecordMsg").hide( );
					$("#DuplicateSource").val("0");
				}
			},

			"text");
	});


	$("#frmRecord").submit(function( )
	{
		var objFV = new FormValidator("frmRecord", "RecordMsg");

		if (!objFV.validate("txtName", "B", "Please enter the Source Name."))
			return false;

		if (objFV.value("DuplicateSource") == "1")
		{
			showMessage("#RecordMsg", "info", "The specified Inquiry Source already exists in the System.");

			objFV.focus("txtName");
			objFV.select("txtName");

			return false;
		}

		$("#frmRecord #BtnSave").attr('disabled', true);
		$("#RecordMsg").hide( );
	});
});


function updateRecord(iSourceId, iRow, sFields)
{
	$("#DataGrid thead tr th").each(function(iIndex)
	{
		if ($(this).text( ) == "Name")
			objTable.fnUpdate(sFields[0], iRow, iIndex, false);

		else if ($(this).text( ) == "Status")
			objTable.fnUpdate(sFields[1], iRow, iIndex, false);
	});


	$("#DataGrid .icnToggle").each(function(iIndex)
	{
		if ($(this).attr("id") == iSourceId)
			$(this).attr("src", sFields[2]);
	});
}

