function parseDate(sDate, bAddDay)
{
	if (typeof bAddDay === "undefined")
		bAddDay = false;

	if (typeof sDate === "undefined")
		return "";


	var sDateFields = sDate.split("-");
	var iYear       = parseInt(sDateFields[0]);
	var iMonth      = (parseInt(sDateFields[1]) - 1);
	var iDay        = parseInt(sDateFields[2]);
	var objDate     = new Date(iYear, iMonth, iDay);


	return new Date(objDate.getTime() + ((bAddDay == true) ? 86400000 : 0));
}


function parseTime(sTime)
{
	if (typeof sTime === "undefined")
		return "";


	var sTimeFields  = sTime.split(" ");
	var sHourMinutes = sTimeFields[0].split(":");
	var iHours       = parseInt(sHourMinutes[0]);
	var iMinutes     = parseInt(sHourMinutes[1]);

	if (sTimeFields[1] == "PM" && iHours < 12)
		iHours += 12;


	var objDate = new Date( );

	objDate.setHours(iHours, iMinutes, 0, 0);


	return objDate.getTime( );
}


function parseDateTime(sDateTime)
{
	if (typeof sDateTime === "undefined")
		return "";


	var sDateTimeFields = sDateTime.split(" ");
	var sDateFields     = sDateTimeFields[0].split("-");
	var sTimeFields     = sDateTimeFields[1].split(":");

	var iYear           = parseInt(sDateFields[0]);
	var iMonth          = (parseInt(sDateFields[1]) - 1);
	var iDay            = parseInt(sDateFields[2]);

	var iHours          = parseInt(sTimeFields[0]);
	var iMinutes        = parseInt(sTimeFields[1]);
	var iSeconds        = parseInt(sTimeFields[2]);


	return new Date(iYear, iMonth, iDay, iHours, iMinutes, iSeconds);
}


function saveAttachment(sIndex, sType, objFile)
{
	var objForm = new FormData( );

   objForm.append('Type', sType);
   objForm.append(('file' + sType), objFile);


	$.ajax(
	{
		xhr          :  function( )
						{
							var objXhr = new window.XMLHttpRequest( );


							objXhr.upload.addEventListener("progress", function(event)
							{
								if (event.lengthComputable)
								{
									var fPercentage = ((event.loaded / event.total) * 100);

									$("#UploadProgress" + sIndex + " .progressBar").width(fPercentage + '%');
									$("#UploadProgress" + sIndex + " .progressBar").html(fPercentage + '%');
								}
							}, false);


							return objXhr;
						},

		type         :  'POST',
		url          :  'ajax/save-attachment.php',
		data         :  objForm,
		contentType  :  false,
		cache        :  false,
		processData  :  false,

		beforeSend   :  function( )
						{
							$("#UploadProgress" + sIndex + " .progressBar").width('0%');
							$("#UploadProgress" + sIndex + " .progressBar").html('0%');

							$("#Attachment" + sIndex).find(".browseField").addClass("hidden");
							$("#Attachment" + sIndex).find(".btnRemove").addClass("hidden");

							$("#Attachment" + sIndex).find(".uploadProgress").removeClass("hidden");
							$("#Attachment" + sIndex).find(".btnRemove").parent( ).append("<img src='images/backup.gif' width='20' alt='' title='' />");
						},

		error        :  function()
						{
							$("#Attachment" + sIndex).find(".uploadProgress").addClass("hidden");
							$("#Attachment" + sIndex).find(".browseField").val("").removeClass("hidden").css("border", "solid 1px #dd0000");

							$("#Attachment" + sIndex).find(".btnRemove").removeClass("hidden");
							$("#Attachment" + sIndex).find(".btnRemove").parent( ).find("img").remove( );
						},

		success      :  function(sResponse)
						{
							if (sResponse == 'OK')
							{
								$("#Attachment" + sIndex).find(".file").val(objFile.name);
								$("#UploadProgress" + sIndex + " .progressBar").html(objFile.name);
								$("#UploadProgress" + sIndex + " .progressBar").addClass("uploaded");
							}

							else
							{
								$("#Attachment" + sIndex).find(".uploadProgress").addClass("hidden");
								$("#Attachment" + sIndex).find(".browseField").val("").removeClass("hidden").css("border", "solid 1px #dd0000");
							}


							$("#Attachment" + sIndex).find(".btnRemove").removeClass("hidden");
							$("#Attachment" + sIndex).find(".btnRemove").parent( ).find("img").remove( );
						}
	});
}


