function initControls( )
{
	$(".count").each(function( )
	{
		$(this).prop('Counter', 0).animate(
		{
			Counter : $(this).text( )
		},
		
		{
			duration  :  500,
			easing    :  'swing',
			
			step      :  function(iIndex)
			{
				$(this).text(Math.ceil(iIndex));
			}
		});
	});
	
	
	$('.chart').easyPieChart(
